SELECT count() AS mismatches FROM (SELECT owner_key,field_name,value,author_key,doc_id,version,sum(weight) AS delta FROM (SELECT owner_key,field_name,value,author_key,doc_id,version,toInt8(1) AS weight FROM (SELECT * FROM strings WHERE startsWith(field_name,'document:')) UNION ALL SELECT owner_key,field_name,value,author_key,doc_id,version,toInt8(-1) AS weight FROM (SELECT doc_id AS owner_key,concat('document:',collection_name) AS field_name,author_key AS value,author_key,doc_id,updated_at AS version FROM documents FINAL WHERE deleted=0)) GROUP BY owner_key,field_name,value,author_key,doc_id,version HAVING delta!=0)
